<?php
if(!defined('ABSPATH')){exit;} final class DSVS_Fetcher { const MAX_RESPONSE_SIZE=1048576; public static function get($url,$duration,$namespace){$key='dsvs_'.sanitize_key($namespace).'_'.md5($url);$cached=get_transient($key);if(false!==$cached){return $cached;}$response=wp_safe_remote_get($url,array('timeout'=>12,'redirection'=>3,'limit_response_size'=>self::MAX_RESPONSE_SIZE,'headers'=>array('Accept'=>'text/html'),'user-agent'=>'DSVS-WP-Plugin/'.DSVS_VERSION.'; '.home_url('/')));if(is_wp_error($response)){return $response;}$code=wp_remote_retrieve_response_code($response);$body=wp_remote_retrieve_body($response);if(200!==$code||strlen($body)<500||strlen($body)>self::MAX_RESPONSE_SIZE||false===stripos($body,'<table')){return new WP_Error('dsvs_invalid_response','Unerwartete DSVS-Antwort.');}set_transient($key,$body,max(30,absint($duration)));return $body;} }
